import threading


class ItemShelf:
    def __init__(self):
        self._quantity = 0
        self._lock = threading.Lock()

    # one atomic check-and-decrement per shelf
    def try_dispense(self) -> bool:
        with self._lock:
            if self._quantity <= 0:
                return False   # nothing left
            self._quantity -= 1
            return True         # this caller won the unit

    def add_stock(self, count: int) -> None:
        with self._lock:
            self._quantity += count

    def is_available(self) -> bool:
        with self._lock:
            return self._quantity > 0

