public class ChangeDispenser {
    private final Map<Coin, Integer> coinFloat = new EnumMap<>(Coin.class);

    public synchronized void add(Coin coin, int count) {
        coinFloat.merge(coin, count, Integer::sum);
    }

    // greedy over descending denominations; standard coins make this optimal
    public synchronized boolean canMakeChange(int amount) {
        return tryPlan(amount) != null;
    }

    public synchronized List<Coin> makeChange(int amount) {
        List<Coin> plan = tryPlan(amount);
        if (plan == null) throw new IllegalStateException("cannot make change for " + amount);
        for (Coin c : plan) coinFloat.merge(c, -1, Integer::sum);   // pay out
        return plan;
    }

    private List<Coin> tryPlan(int amount) {
        List<Coin> plan = new ArrayList<>();
        int remaining = amount;
        Coin[] byValueDesc = { Coin.FIVE, Coin.ONE, Coin.QUARTER, Coin.DIME, Coin.NICKEL, Coin.PENNY };
        for (Coin c : byValueDesc) {
            int available = coinFloat.getOrDefault(c, 0);
            while (remaining >= c.value && available > 0) {
                plan.add(c);
                remaining -= c.value;
                available--;
            }
        }
        return remaining == 0 ? plan : null;
    }
}

