#include <map>
#include <mutex>
#include <optional>
#include <stdexcept>
#include <vector>

enum class Coin { PENNY = 1, NICKEL = 5, DIME = 10, QUARTER = 25, ONE = 100, FIVE = 500 };

class ChangeDispenser {
public:
    void add(Coin coin, int count) { std::lock_guard<std::mutex> l(mu_); coinFloat_[coin] += count; }

    // greedy over descending denominations; standard coins make this optimal
    bool canMakeChange(int amount) { std::lock_guard<std::mutex> l(mu_); return tryPlan(amount).has_value(); }

    std::vector<Coin> makeChange(int amount) {
        std::lock_guard<std::mutex> l(mu_);
        auto plan = tryPlan(amount);
        if (!plan) throw std::runtime_error("cannot make change for " + std::to_string(amount));
        for (Coin c : *plan) coinFloat_[c]--;    // pay out
        return *plan;
    }

private:
    std::optional<std::vector<Coin>> tryPlan(int amount) {
        std::vector<Coin> plan;
        int remaining = amount;
        std::vector<Coin> byValueDesc = { Coin::FIVE, Coin::ONE, Coin::QUARTER, Coin::DIME, Coin::NICKEL, Coin::PENNY };
        for (Coin c : byValueDesc) {
            int available = coinFloat_.count(c) ? coinFloat_[c] : 0;
            while (remaining >= static_cast<int>(c) && available > 0) {
                plan.push_back(c);
                remaining -= static_cast<int>(c);
                available--;
            }
        }
        if (remaining == 0) return plan;
        return std::nullopt;
    }

    std::map<Coin, int> coinFloat_;
    std::mutex mu_;
};

