import threading
from enum import Enum
from typing import Dict, List, Optional


class Coin(Enum):
    PENNY = 1
    NICKEL = 5
    DIME = 10
    QUARTER = 25
    ONE = 100
    FIVE = 500


class ChangeDispenser:
    def __init__(self):
        self._coin_float: Dict[Coin, int] = {}
        self._lock = threading.Lock()

    def add(self, coin: Coin, count: int) -> None:
        with self._lock:
            self._coin_float[coin] = self._coin_float.get(coin, 0) + count

    # greedy over descending denominations; standard coins make this optimal
    def can_make_change(self, amount: int) -> bool:
        with self._lock:
            return self._try_plan(amount) is not None

    def make_change(self, amount: int) -> List[Coin]:
        with self._lock:
            plan = self._try_plan(amount)
            if plan is None:
                raise RuntimeError(f"cannot make change for {amount}")
            for c in plan:
                self._coin_float[c] -= 1     # pay out
            return plan

    def _try_plan(self, amount: int) -> Optional[List[Coin]]:
        plan: List[Coin] = []
        remaining = amount
        by_value_desc = [Coin.FIVE, Coin.ONE, Coin.QUARTER, Coin.DIME, Coin.NICKEL, Coin.PENNY]
        for c in by_value_desc:
            available = self._coin_float.get(c, 0)
            while remaining >= c.value and available > 0:
                plan.append(c)
                remaining -= c.value
                available -= 1
        return plan if remaining == 0 else None

