public interface State {
    void insertMoney(VendingMachine m, Coin coin);
    void selectItem(VendingMachine m, String code);
    void dispense(VendingMachine m);
    void refund(VendingMachine m);
}

public class IdleState implements State {
    public void insertMoney(VendingMachine m, Coin coin) {
        m.addBalance(coin);
        m.setState(new HasMoneyState());        // first money starts a session
    }
    public void selectItem(VendingMachine m, String code) {
        throw new IllegalStateException("Insert money first");
    }
    public void dispense(VendingMachine m) {
        throw new IllegalStateException("Nothing selected");
    }
    public void refund(VendingMachine m) {
        throw new IllegalStateException("No money to refund");
    }
}

public class HasMoneyState implements State {
    public void insertMoney(VendingMachine m, Coin coin) {
        m.addBalance(coin);                      // keep accepting money
    }
    public void selectItem(VendingMachine m, String code) {
        ItemShelf shelf = m.getInventory().getShelf(code);
        if (shelf == null) throw new InvalidSelectionException(code);
        if (!shelf.isAvailable()) throw new OutOfStockException(code);
        int price = shelf.getItem().getPrice();
        if (m.getBalance() < price)
            throw new InsufficientBalanceException(price, m.getBalance());
        if (!m.getDispenser().canMakeChange(m.getBalance() - price))
            throw new ChangeUnavailableException();
        m.setSelected(code);
        m.setState(new DispenseState());
    }
    public void dispense(VendingMachine m) {
        throw new IllegalStateException("Select an item first");
    }
    public void refund(VendingMachine m) {
        m.refundBalance();
        m.setState(new IdleState());
    }
}

public class DispenseState implements State {
    public void insertMoney(VendingMachine m, Coin coin) {
        throw new IllegalStateException("Dispensing in progress");
    }
    public void selectItem(VendingMachine m, String code) {
        throw new IllegalStateException("Already dispensing");
    }
    public void dispense(VendingMachine m) {
        ItemShelf shelf = m.getInventory().getShelf(m.getSelected());
        if (!shelf.tryDispense()) {              // atomic last-item guard
            m.refundBalance();
            m.setState(new IdleState());
            throw new OutOfStockException(m.getSelected());
        }
        int change = m.getBalance() - shelf.getItem().getPrice();
        List<Coin> coins = m.getDispenser().makeChange(change);
        m.deliver(shelf.getItem(), coins);
        m.reset();
        m.setState(new IdleState());
    }
    public void refund(VendingMachine m) {
        m.refundBalance();
        m.setState(new IdleState());
    }
}

