    def insert_money(self, m, coin):
        m.add_balance(coin)
        m.set_state(HasMoneyState())          # first money starts a session

    def select_item(self, m, code): raise RuntimeError("Insert money first")
    def dispense(self, m): raise RuntimeError("Nothing selected")
