    def insert_money(self, m, coin):
        m.add_balance(coin)                    # keep accepting money

    def select_item(self, m, code):
        shelf = m.get_inventory().get_shelf(code)
        if shelf is None:
            raise InvalidSelectionException(code)
        if not shelf.is_available():
            raise OutOfStockException(code)
        price = shelf.get_item().get_price()
        if m.get_balance() < price:
            raise InsufficientBalanceException(price, m.get_balance())
        if not m.get_dispenser().can_make_change(m.get_balance() - price):
