    public void restock(String code, int count) { inventory.getShelf(code).addStock(count); }
    public void refillCoins(Coin c, int count) { dispenser.add(c, count); }

    // callbacks used by states
    void setState(State s) { this.state = s; }
    void addBalance(Coin c) { balance += c.value; dispenser.add(c, 1); }
    int getBalance() { return balance; }
    Inventory getInventory() { return inventory; }
    ChangeDispenser getDispenser() { return dispenser; }
    void setSelected(String code) { this.selectedCode = code; }
    String getSelected() { return selectedCode; }
    void reset() { balance = 0; selectedCode = null; }
    void refundBalance() { deliver(null, dispenser.makeChange(balance)); reset(); }
    void deliver(Item item, List<Coin> change) {
        if (item != null) System.out.println("Dispensed: " + item.getName());
        if (!change.isEmpty()) System.out.println("Change: " + change);
