    def refund(self) -> None: self._state.refund(self)

    # operator facing
    def restock(self, code: str, count: int) -> None: self._inventory.get_shelf(code).add_stock(count)
    def refill_coins(self, c: Coin, count: int) -> None: self._dispenser.add(c, count)

    # callbacks used by states
    def set_state(self, s: "State") -> None: self._state = s
    def add_balance(self, c: Coin) -> None:
        self._balance += c.value
        self._dispenser.add(c, 1)
    def get_balance(self) -> int: return self._balance
    def get_inventory(self) -> Inventory: return self._inventory
    def get_dispenser(self) -> ChangeDispenser: return self._dispenser
    def set_selected(self, code: str) -> None: self._selected_code = code
    def get_selected(self) -> str: return self._selected_code
    def reset(self) -> None:
        self._balance = 0
        self._selected_code = None
    def refund_balance(self) -> None:
        self.deliver(None, self._dispenser.make_change(self._balance))
        self.reset()
    def deliver(self, item: Optional["Item"], change: List[Coin]) -> None:
        if item is not None:
            print(f"Dispensed: {item.get_name()}")
        if change:
            print(f"Change: {[c.name for c in change]}")

